        parameters: {
            query?: {
                reason?: "hard_bounce" | "complaint" | "unsubscribe" | "manual";
                source?: "cloudflare" | "events" | "manual" | "import";
                cloudflare?: "in-sync" | "missing" | "not-applicable" | "unchecked";
                q?: string;
                cursor?: string;
                limit?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Success */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        suppressions: {
                            email: string;
                            /** @enum {string} */
                            reason: "hard_bounce" | "complaint" | "unsubscribe" | "manual";
                            /**
                             * @description events: a bounce or complaint event. cloudflare: Cloudflare refused a send, or the sync adopted it from Cloudflare's list. manual: added through the API. import: a suppression CSV.
                             * @enum {string}
                             */
                            source: "cloudflare" | "events" | "manual" | "import";
                            /** @description The message whose bounce or complaint added it. */
                            messageId: string | null;
                            note: string | null;
                            /** @description Blocks only campaigns and automations; transactional and mailbox mail still go. Always true for unsubscribes. */
                            bulkOnly: boolean;
                            streams: ("all" | "campaign" | "automation")[];
                            /**
                             * @description Whether Cloudflare's Email Sending suppression list agrees. in-sync: it has the address. missing: the last sync didn't find it (push it). not-applicable: an unsubscribe or bulk-only row, which Cloudflare's list must not hold, since it blocks transactional mail too. unchecked: no sync has looked yet, or Mailyard can't read the list.
                             * @enum {string}
                             */
                            cloudflare: "in-sync" | "missing" | "not-applicable" | "unchecked";
                            at: number | ("Infinity" | "-Infinity" | "NaN");
                            updatedAt: number | ("Infinity" | "-Infinity" | "NaN");
                        }[];
                        counts: {
                            total: number | ("Infinity" | "-Infinity" | "NaN");
                            hard_bounce: number | ("Infinity" | "-Infinity" | "NaN");
                            complaint: number | ("Infinity" | "-Infinity" | "NaN");
                            unsubscribe: number | ("Infinity" | "-Infinity" | "NaN");
                            manual: number | ("Infinity" | "-Infinity" | "NaN");
                        };
                        cloudflare: {
                            readable: boolean;
                            writable: boolean;
                            checkedAt: (number | ("Infinity" | "-Infinity" | "NaN")) | null;
                            cloudflareOnly: number | ("Infinity" | "-Infinity" | "NaN");
                            error: string | null;
                        };
                        nextCursor: string | null;
                    };
                };
            };
            /** @description InvalidRequest */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["InvalidRequestEncoded"];
                };
            };
            /** @description Unauthorized */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["UnauthorizedEncoded"];
                };
            };
            /** @description Forbidden */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ForbiddenEncoded"];
                };
            };
            /** @description RateLimited */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["RateLimitedEncoded"];
                };
            };
        };
