    "integrations.get": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Success */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        mcp: {
                            endpoint: string | null;
                            keyCount: number | ("Infinity" | "-Infinity" | "NaN");
                            agentCount: number | ("Infinity" | "-Infinity" | "NaN");
                            lastUsedAt: (number | ("Infinity" | "-Infinity" | "NaN")) | null;
                            keys: {
                                id: string;
                                name: string;
                                prefix: string;
                                scopes: string[];
                                lastUsedAt: (number | ("Infinity" | "-Infinity" | "NaN")) | null;
                                createdAt: number | ("Infinity" | "-Infinity" | "NaN");
                                agent: {
                                    id: string;
                                    name: string;
                                    mailboxId: string;
                                    address: string | null;
                                } | null;
                            }[] | null;
                        };
                        webhooks: {
                            count: number | ("Infinity" | "-Infinity" | "NaN");
                            enabled: number | ("Infinity" | "-Infinity" | "NaN");
                            paused: number | ("Infinity" | "-Infinity" | "NaN");
                            failing: number | ("Infinity" | "-Infinity" | "NaN");
                            deadLetters: number | ("Infinity" | "-Infinity" | "NaN");
                            held: number | ("Infinity" | "-Infinity" | "NaN");
                            failingEndpoints: {
                                id: string;
                                url: string;
                                deadLetters: number | ("Infinity" | "-Infinity" | "NaN");
                                lastFailureAt: (number | ("Infinity" | "-Infinity" | "NaN")) | null;
                                lastSuccessAt: (number | ("Infinity" | "-Infinity" | "NaN")) | null;
                            }[];
                        };
                        hermes: {
                            connected: boolean;
                            lane: string | null;
                            mailboxes: string[];
                            allMailboxes: boolean;
                            since: (number | ("Infinity" | "-Infinity" | "NaN")) | null;
                            available: boolean;
                        };
                        siblings: {
                            app: string;
                            name: string;
                            /** @enum {string} */
                            via: "mcp" | "queue";
                            connected: boolean;
                            keyId: string | null;
                            lastUsedAt: (number | ("Infinity" | "-Infinity" | "NaN")) | null;
                        }[];
                    };
                };
            };
            /** @description Unauthorized */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["UnauthorizedEncoded"];
                };
            };
            /** @description Forbidden */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ForbiddenEncoded"];
                };
            };
            /** @description RateLimited */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["RateLimitedEncoded"];
                };
            };
        };
    };
    "mcp.rpc": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": Record<string, never>;
            };
        };
        responses: {
            /** @description The JSON-RPC response (or array of them). */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": Record<string, never>;
                };
            };
            /** @description Only notifications: accepted. */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Not JSON-RPC, or an unsupported MCP-Protocol-Version. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error?: {
                            message?: string;
                            reason?: string;
                        };
                    };
                };
            };
            /** @description No key, or not a key Mailyard knows. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error?: {
                            message?: string;
                            reason?: string;
                        };
                    };
                };
            };
            /** @description A public key. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error?: {
                            message?: string;
                            reason?: string;
                        };
                    };
                };
            };
            /** @description Not a POST. */
            405: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error?: {
                            message?: string;
                            reason?: string;
                        };
                    };
                };
            };
        };
    };
