    "mail.wait": {
        parameters: {
            query?: {
                /** @description The cursor from the last answer. */
                since?: number;
                /** @description Seconds to wait. */
                timeout?: number;
            };
            header?: never;
            path: {
                /** @description The mailbox. */
                id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Mail arrived. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        cursor: number;
                        reset: boolean;
                        messages: {
                            id?: string;
                            threadId?: string;
                            subject?: string;
                            from?: Record<string, never> | null;
                            snippet?: string;
                            receivedAt?: number;
                            folder?: string;
                            seen?: boolean;
                        }[];
                    };
                };
            };
            /** @description Nothing arrived before the timeout; the cursor is in x-mailyard-cursor. */
            204: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description since or timeout isn't valid. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error?: {
                            message?: string;
                            reason?: string;
                        };
                    };
                };
            };
            /** @description No key or session, or one that no longer works. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error?: {
                            message?: string;
                            reason?: string;
                        };
                    };
                };
            };
            /** @description The key can't read this mailbox. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error?: {
                            message?: string;
                            reason?: string;
                        };
                    };
                };
            };
            /** @description No such mailbox. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        error?: {
                            message?: string;
                            reason?: string;
                        };
                    };
                };
            };
        };
    };
